from collections.abc import Iterable

def flatten_list(collection):
    result = []
    if isinstance(collection, str):
        # Strings are iterable but should be treated as atomic
        result.append(collection)
    elif isinstance(collection, dict):
        # For dicts, iterate over keys and values
        for key in collection:
            result.extend(flatten_list(key))
            result.extend(flatten_list(collection[key]))
    elif isinstance(collection, Iterable):
        for item in collection:
            result.extend(flatten_list(item))
    else:
        # Non-iterable element
        result.append(collection)
    return result

