import math

def min_Jumps(d, move_length):
    d = abs(d)
    if d == 0:
        return 0
    # If one move is enough (d == move_length)
    if d == move_length:
        return 1
    # If one move is longer than distance, but can't reach exactly in one move
    if d < move_length:
        return 2
    # For d > move_length:
    # minimal moves needed is ceiling of d/move_length
    # except when d is exactly multiple of move_length, then it's d/move_length
    # (covered by ceiling)
    return math.ceil(d / move_length)

